@Override
    @SuppressWarnings("unchecked")
    public <T> T convert(Object value, Class<T> type) throws ELException {

        if (type == URI.class && value instanceof String) {
            return (T) URI.create((String) value);
        }

        return super.convert(value, type);
    }
